functionnormalizeSkillName(name: string): string{

returnname.toLowerCase().replace(/\[\\s\_\]+/g,'-');

}

functionnormalizeRelativePath(path: string): string{

returnpath.split(sep).join('/').replace(/\\/+/g,'/');

}

/\*\*

\\* Check if internal skills should be installed.

\\* Internal skills are hidden by default unless INSTALL\_INTERNAL\_SKILLS=1 is set.

\*/

exportfunctionshouldInstallInternalSkills(): boolean{

constenvValue=process.env.INSTALL\_INTERNAL\_SKILLS;

returnenvValue==='1'\|\|envValue==='true';

}

asyncfunctionhasSkillMd(dir: string): Promise<boolean>{

try{

constskillPath=join(dir,'SKILL.md');

conststats=awaitstat(skillPath);

returnstats.isFile();

}catch{

returnfalse;

}

}

exportasyncfunctionparseSkillMd(

skillMdPath: string,

options?: {includeInternal?: boolean}

): Promise<Skill\|null>{

try{

constcontent=awaitreadFile(skillMdPath,'utf-8');

const{ data }=parseFrontmatter(content);

if(!data.name\|\|!data.description){

returnnull;

}

// Ensure name and description are strings (YAML can parse numbers, booleans, etc.)

if(typeofdata.name!=='string'\|\|typeofdata.description!=='string'){

returnnull;

}

// Skip internal skills unless:

// 1\. INSTALL\_INTERNAL\_SKILLS=1 is set, OR

// 2\. includeInternal option is true (e.g., when user explicitly requests a skill)

constisInternal=data.metadata?.internal===true;

if(isInternal&&!shouldInstallInternalSkills()&&!options?.includeInternal){

returnnull;

}

return{

name: sanitizeMetadata(data.name),

description: sanitizeMetadata(data.description),

path: dirname(skillMdPath),

rawContent: content,

metadata: data.metadata,

};

}catch{

returnnull;

}

}

asyncfunctionfindSkillDirs(dir: string,depth=0,maxDepth=5): Promise<string\[\]>{

if(depth>maxDepth)return\[\];

try{

const\[hasSkill,entries\]=awaitPromise.all(\[\
\
hasSkillMd(dir),\
\
readdir(dir,{withFileTypes: true}).catch(()=>\[\]),\
\
\]);

constcurrentDir=hasSkill ? \[dir\] : \[\];

// Search subdirectories in parallel

constsubDirResults=awaitPromise.all(

entries

.filter((entry)=>entry.isDirectory()&&!SKIP\_DIRS.includes(entry.name))

.map((entry)=>findSkillDirs(join(dir,entry.name),depth+1,maxDepth))

);

return\[...currentDir, ...subDirResults.flat()\];

}catch{

return\[\];

}

}

exportinterfaceDiscoverSkillsOptions{

/\\*\\* Include internal skills (e.g., when user explicitly requests a skill by name) \*/

includeInternal?: boolean;

/\\*\\* Search all subdirectories even when a root SKILL.md exists \*/

fullDepth?: boolean;

}

/\*\*

\\* Validates that a resolved subpath stays within the base directory.

\\* Prevents path traversal attacks where subpath contains ".." segments

\\* that would escape the cloned repository directory.

\*/

exportfunctionisSubpathSafe(basePath: string,subpath: string): boolean{

constnormalizedBase=normalize(resolve(basePath));

constnormalizedTarget=normalize(resolve(join(basePath,subpath)));

returnnormalizedTarget.startsWith(normalizedBase+sep)\|\|normalizedTarget===normalizedBase;

}

exportasyncfunctiondiscoverSkills(

basePath: string,

subpath?: string,

options?: DiscoverSkillsOptions

): Promise<Skill\[\]>{

constskills: Skill\[\]=\[\];

constseenNames=newSet<string>();

constlocalLock=awaitreadLocalLock(basePath);

constlockedSkillNames=newSet(Object.keys(localLock.skills).map(normalizeSkillName));

// Validate subpath doesn't escape basePath (prevent path traversal)

if(subpath&&!isSubpathSafe(basePath,subpath)){

thrownewError(

\`Invalid subpath: "${subpath}" resolves outside the repository directory. Subpath must not contain ".." segments that escape the base path.\`

);

}

constsearchPath=subpath ? join(basePath,subpath) : basePath;

// Get plugin groupings to map skills to their parent plugin

// We search for plugin definitions from the base search path

constpluginGroupings=awaitgetPluginGroupings(searchPath);

// Helper to assign plugin name if available

constenhanceSkill=(skill: Skill)=>{

constresolvedPath=resolve(skill.path);

if(pluginGroupings.has(resolvedPath)){

skill.pluginName=pluginGroupings.get(resolvedPath);

}

returnskill;

};

constisInstalledProjectSkill=(skill: Skill): boolean=>{

if(lockedSkillNames.size===0)returnfalse;

constrelativeDir=normalizeRelativePath(relative(basePath,skill.path));

constisAgentSkillPath=AGENT\_PROJECT\_SKILL\_DIRS.some(

(dir)=>relativeDir===dir\|\|relativeDir.startsWith(\`${dir}/\`)

);

if(!isAgentSkillPath)returnfalse;

constskillName=normalizeSkillName(skill.name);

constdirectoryName=normalizeSkillName(basename(skill.path));

returnlockedSkillNames.has(skillName)\|\|lockedSkillNames.has(directoryName);

};

// If pointing directly at a skill, add it (and return early unless fullDepth is set).

// If the root SKILL.md is an installed project skill tracked by skills-lock.json,

// ignore it and continue scanning in case the repo also contains source skills.

if(awaithasSkillMd(searchPath)){

letskill=awaitparseSkillMd(join(searchPath,'SKILL.md'),options);

if(skill){

if(!isInstalledProjectSkill(skill)){

skill=enhanceSkill(skill);

skills.push(skill);

seenNames.add(skill.name);

// Only return early if fullDepth is not set

if(!options?.fullDepth){

returnskills;

}

}

}

}

// Search common skill locations first

constprioritySearchDirs=\[\
\
searchPath,\
\
join(searchPath,'skills'),\
\
join(searchPath,'skills/.curated'),\
\
join(searchPath,'skills/.experimental'),\
\
join(searchPath,'skills/.system'),\
\
...AGENT\_PROJECT\_SKILL\_DIRS.map((dir)=>join(searchPath,dir)),\
\
\];

// Known skill container dirs are walked one extra level deep so layouts

// like \`skills/<category>/<skill>/SKILL.md\` are discovered without

// requiring \`--full-depth\`. The repo root (first entry) keeps its

// existing depth-1 behavior to avoid surfacing unrelated \`SKILL.md\`

// files (e.g. \`examples/foo/SKILL.md\`), and plugin-manifest-declared

// dirs (appended below) stay at depth-1 to honor the manifest spec.

constdeepContainerDirs=newSet(prioritySearchDirs.slice(1));

// Add skill paths declared in plugin manifests

prioritySearchDirs.push(...(awaitgetPluginSkillPaths(searchPath)));

consttryAddSkillAt=async(skillDir: string): Promise<boolean>=>{

if(!(awaithasSkillMd(skillDir)))returnfalse;

letskill=awaitparseSkillMd(join(skillDir,'SKILL.md'),options);

if(!skill\|\|seenNames.has(skill.name))returntrue;

if(isInstalledProjectSkill(skill))returntrue;

skill=enhanceSkill(skill);

skills.push(skill);

seenNames.add(skill.name);

returntrue;

};

for(constdirofprioritySearchDirs){

constwalkDeep=deepContainerDirs.has(dir);

try{

constentries=awaitreaddir(dir,{withFileTypes: true});

for(constentryofentries){

if(!entry.isDirectory())continue;

constchildDir=join(dir,entry.name);

constfoundAtChild=awaittryAddSkillAt(childDir);

// Don't descend past a discovered SKILL.md (matches the existing

// flat-layout semantics) and don't go deeper inside non-container

// priority dirs.

if(foundAtChild\|\|!walkDeep)continue;

if(SKIP\_DIRS.includes(entry.name))continue;

// Walk one extra level for catalog layouts.

try{

constgrandEntries=awaitreaddir(childDir,{withFileTypes: true});

for(constgrandofgrandEntries){

if(!grand.isDirectory()\|\|SKIP\_DIRS.includes(grand.name))continue;

awaittryAddSkillAt(join(childDir,grand.name));

}

}catch{

// Child dir unreadable; skip silently.

}

}

}catch{

// Directory doesn't exist

}

}

// Fall back to recursive search if nothing found, or if fullDepth is set

if(skills.length===0\|\|options?.fullDepth){

constallSkillDirs=awaitfindSkillDirs(searchPath);

for(constskillDirofallSkillDirs){

letskill=awaitparseSkillMd(join(skillDir,'SKILL.md'),options);

if(skill&&!seenNames.has(skill.name)&&!isInstalledProjectSkill(skill)){

skill=enhanceSkill(skill);

skills.push(skill);

seenNames.add(skill.name);

}

}

}

returnskills;

}

exportfunctiongetSkillDisplayName(skill: Skill): string{

returnskill.name\|\|basename(skill.path);

}

/\*\*

\\* Filter skills based on user input (case-insensitive direct matching).

\\* Multi-word skill names must be quoted on the command line.

\*/

exportfunctionfilterSkills(skills: Skill\[\],inputNames: string\[\]): Skill\[\]{

constnormalizedInputs=inputNames.map((n)=>n.toLowerCase());

returnskills.filter((skill)=>{

constname=skill.name.toLowerCase();

constdisplayName=getSkillDisplayName(skill).toLowerCase();

returnnormalizedInputs.some((input)=>input===name\|\|input===displayName);

});

}

