importsimpleGitfrom'simple-git';

import{join,normalize,resolve,sep}from'path';

import{mkdtemp,mkdir,rm}from'fs/promises';

import{tmpdir}from'os';

import{execFile}from'child\_process';

import{promisify}from'util';

constDEFAULT\_CLONE\_TIMEOUT\_MS=300\_000;// 5 minutes

constCLONE\_TIMEOUT\_MS=(()=>{

constraw=process.env.SKILLS\_CLONE\_TIMEOUT\_MS;

if(!raw)returnDEFAULT\_CLONE\_TIMEOUT\_MS;

constparsed=Number.parseInt(raw,10);

returnNumber.isFinite(parsed)&&parsed>0 ? parsed : DEFAULT\_CLONE\_TIMEOUT\_MS;

})();

constexecFileAsync=promisify(execFile);

interfaceGitHubRepoInfo{

owner: string;

repo: string;

slug: string;

sshUrl: string;

}

exportclassGitCloneErrorextendsError{

readonlyurl: string;

readonlyisTimeout: boolean;

readonlyisAuthError: boolean;

constructor(message: string,url: string,isTimeout=false,isAuthError=false){

super(message);

this.name='GitCloneError';

this.url=url;

this.isTimeout=isTimeout;

this.isAuthError=isAuthError;

}

}

exportfunctionparseGitHubRepoUrl(url: string): GitHubRepoInfo\|null{

constsshMatch=url.match(/^git@github\\.com:(\[^/\]+)\\/(\[^/\]+?)(?:\\.git)?$/i);

if(sshMatch){

constowner=sshMatch\[1\]!;

constrepo=sshMatch\[2\]!;

return{

owner,

repo,

slug: \`${owner}/${repo}\`,

sshUrl: \`git@github.com:${owner}/${repo}.git\`,

};

}

try{

constparsed=newURL(url);

if(parsed.hostname!=='github.com')returnnull;

constmatch=parsed.pathname.match(/^\\/(\[^/\]+)\\/(\[^/\]+?)(?:\\.git)?\\/?$/);

if(!match)returnnull;

constowner=match\[1\]!;

constrepo=match\[2\]!;

return{

owner,

repo,

slug: \`${owner}/${repo}\`,

sshUrl: \`git@github.com:${owner}/${repo}.git\`,

};

}catch{

returnnull;

}

}

exportfunctionisGitHubHttpsCloneUrl(url: string): boolean{

try{

constparsed=newURL(url);

returnparsed.protocol==='https:'&&parsed.hostname==='github.com';

}catch{

returnfalse;

}

}

exportfunctionisGitHubSsoAuthError(message: string): boolean{

constlower=message.toLowerCase();

return(

lower.includes('saml sso')\|\|

lower.includes('enforced sso')\|\|

lower.includes('enabled or enforced saml')\|\|

lower.includes('re-authorize the oauth application')

);

}

functionisAuthFailure(message: string): boolean{

return(

message.includes('Authentication failed')\|\|

message.includes('could not read Username')\|\|

message.includes('Permission denied')\|\|

message.includes('Repository not found')\|\|

message.includes('requested URL returned error: 403')\|\|

isGitHubSsoAuthError(message)

);

}

functioncreateGitClient(extraEnv?: NodeJS.ProcessEnv){

returnsimpleGit({

timeout: {block: CLONE\_TIMEOUT\_MS},

env: {

...process.env,

GIT\_TERMINAL\_PROMPT: '0',

// When git-lfs IS installed, tell it not to download LFS content

// during checkout. See #952 for context and empirical impact.

GIT\_LFS\_SKIP\_SMUDGE: '1',

...extraEnv,

},

// When git-lfs is NOT installed, GIT\_LFS\_SKIP\_SMUDGE has no effect —

// git sees \`filter=lfs\` in .gitattributes, tries to run

// \`git-lfs filter-process\`, and aborts the checkout with:

// git-lfs filter-process: git-lfs: command not found

// fatal: the remote end hung up unexpectedly

// warning: Clone succeeded, but checkout failed.

// Overriding filter.lfs.\* at the command level disables the filter

// entirely for this clone, so checkout succeeds regardless of whether

// git-lfs is installed. LFS-tracked files are left as ~130-byte

// pointer files, which the skills installer doesn't read anyway

// (skills are plain text — HTML/MD/JSON — never LFS-tracked).

//

// Reported downstream: heygen-com/hyperframes#407.

config: \[\
\
'filter.lfs.required=false',\
\
'filter.lfs.smudge=',\
\
'filter.lfs.clean=',\
\
'filter.lfs.process=',\
\
\],

});

}

asyncfunctionresetTempDir(dir: string): Promise<void>{

awaitrm(dir,{recursive: true,force: true}).catch(()=>{});

awaitmkdir(dir,{recursive: true});

}

asyncfunctiontryGhClone(repo: GitHubRepoInfo,tempDir: string,ref?: string): Promise<boolean>{

letcloneTarget=repo.slug;

try{

const{ stdout, stderr }=awaitexecFileAsync('gh',\['auth','status','-h','github.com'\],{

timeout: 5000,

env: { ...process.env,GIT\_TERMINAL\_PROMPT: '0'},

});

conststatusOutput=\`${stdout}${stderr}\`;

if(/Gitoperationsprotocol:\\s+ssh/i.test(statusOutput)){

cloneTarget=repo.sshUrl;

}

}catch{

returnfalse;

}

constgitFlags=ref ? \['--depth=1','--branch',ref\] : \['--depth=1'\];

awaitexecFileAsync('gh',\['repo','clone',cloneTarget,tempDir,'--', ...gitFlags\],{

timeout: CLONE\_TIMEOUT\_MS,

env: { ...process.env,GIT\_TERMINAL\_PROMPT: '0'},

});

returntrue;

